import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";

export default function (eleventyConfig) {
  // Passthrough copy for assets (css, js, images). JS is copied by glob
  // (not the whole directory) so the Datadog RUM source map
  // (src/assets/js/rum-init.js.map) is never published to GitHub Pages:
  // it is generated by `npm run bundle:rum` and uploaded to Datadog with
  // `npm run upload:sourcemaps` instead.
  eleventyConfig.addPassthroughCopy("src/assets/css");
  eleventyConfig.addPassthroughCopy("src/assets/img");
  eleventyConfig.addPassthroughCopy("src/assets/js/*.js");

  // Passthrough copy for root-level files
  eleventyConfig.addPassthroughCopy({
    "src/robots.txt": "robots.txt",
    "src/.nojekyll": ".nojekyll"
  });

  // Cache-busting: append a short content hash to local asset URLs so
  // pushes are picked up immediately instead of serving stale cached copies.
  // Zero-pad a number to two digits (e.g. 5 -> "05") for design stats/numbering.
  eleventyConfig.addFilter("pad2", (n) => String(n).padStart(2, "0"));

  eleventyConfig.addFilter("cacheBust", (url) => {
    try {
      const file = join("src", String(url).replace(/^\//, "").split("?")[0]);
      const hash = createHash("md5").update(readFileSync(file)).digest("hex").slice(0, 8);
      return `${url}?v=${hash}`;
    } catch {
      return url;
    }
  });

  return {
    dir: {
      input: "src",
      output: "docs",
      includes: "_includes",
    },
  };
}
